  const state = { ws: 'site', R: 450, site: null, blocks: [], access: null, keepExisting: true, existing: [], params: Object.assign({}, Demand.DEFAULTS, { win: 'pm', t0: 16.5, t1: 18, seed: 1, sidewalkScale: 1, maxAgents: 12000, maxVeh: 20000 }), view: { mode: 'live', scenario: 'proposed', layers: { labels: true, network: true, byGroup: false } }, people: Demand.defaultPeople(), results: {}, cmp: null, sims: {}, live: null, playing: false, speed: 20, running: false, prog: 0, hover: null, sel: null, net: null, dm: null, model: null, walk: null, dirty: true, importedName: '' };
