    const context = Site.buildingsNear(s.centre, state.R, s.ring); const parks = Site.parksNear(s.centre, state.R); const stops = window.OSMS.stops.filter((x) => G.dist([x.x, x.y], s.centre) <= state.R + 30);
    const frontEdge = s.edges.find((e) => e.front) || s.edges[0]; const frontMid = [(frontEdge.A[0] + frontEdge.B[0]) / 2, (frontEdge.A[1] + frontEdge.B[1]) / 2];
