  function scheduleRebuild() { state.dirty = true; state.results = {}; state.cmp = null; state.live = null; state.playing = false; clearTimeout(rebuildTimer); rebuildTimer = setTimeout(() => { rebuild(); render(); }, 250); }

  /* ---------- running ---------- */
