  function scales(dm) { const { t0, t1 } = windowSeconds(); const a = Demand.expected(dm, 'baseline', t0, t1), b = Demand.expected(dm, 'proposed', t0, t1); const ped = Math.max(a.ped, b.ped), veh = Math.max(a.veh, b.veh); return { kPed: Math.max(1, Math.ceil(ped / state.params.maxAgents)), kVeh: Math.max(1, Math.ceil(veh / state.params.maxVeh)), expPed: ped, expVeh: veh }; }
