  /* ---------- view state for the canvas ---------- */
  function viewState() {
    const scn = state.view.scenario; const res = state.results[scn] || null;
    return { net: state.net, res, cmp: state.cmp, mode: state.view.mode, scenario: scn, site: state.site, footprints: footprints(), existingFoot: existingBlocks(), entrances: resolvedEntrances(), spaces: resolvedSpaces(), context: state.model ? state.model.context : [], parks: state.model ? state.model.parks : [], stops: state.model ? state.model.stops : [], centre: state.site.centre, R: state.R, layers: state.view.layers, live: !!state.live && (state.playing || state.view.mode === 'live'), sim: state.live, gens: state.dm ? state.dm.gens : null, walk: state.walk, hasProposed: state.blocks.length > 0 };
  }
