  function render() { const cur = state.ws === 'report' ? 'results' : state.ws; document.querySelectorAll('#tabs button').forEach((b) => b.classList.toggle('on', b.dataset.ws === cur)); renderRunbar(); document.body.dataset.ws = state.ws; renderLeft(); renderRight(); renderMapbar(); renderLegend(); renderStatus(); Views.invalidate(); }
